#include "harness.hpp"

#include <opencv2/imgproc.hpp>

#include "tinyvision/preprocess.hpp"

// --- Resize parity: cv2.INTER_AREA golden (generated by numpy/cv2). ----
// Golden src/dst hold plain 3-channel pixels (no BGR interpretation); this test
// pins OpenCV-C++ cv::resize == cv2.resize for the identical byte input.
TEST(ResizeAreaMatchesCv2Golden) {
  const std::vector<uint8_t> src =
      tv_testing::LoadNpyU8("runtime/tests/golden_resize_area_src.npy");  // 16x32x3
  const std::vector<float> dst =
      tv_testing::LoadNpyF32("runtime/tests/golden_resize_area_dst.npy");  // 8x8x3

  cv::Mat rgb(16, 32, CV_8UC3);
  for (int y = 0; y < 16; ++y) {
    for (int x = 0; x < 32; ++x) {
      cv::Vec3b& px = rgb.at<cv::Vec3b>(y, x);
      px[0] = src[(y * 32 + x) * 3 + 0];
      px[1] = src[(y * 32 + x) * 3 + 1];
      px[2] = src[(y * 32 + x) * 3 + 2];
    }
  }

  cv::Mat out;
  cv::resize(rgb, out, cv::Size(8, 8), 0, 0, cv::INTER_AREA);
  CHECK(out.cols == 8 && out.rows == 8);
  CHECK(out.type() == CV_8UC3);

  for (int y = 0; y < 8; ++y) {
    for (int x = 0; x < 8; ++x) {
      const cv::Vec3b& px = out.at<cv::Vec3b>(y, x);
      for (int c = 0; c < 3; ++c) {
        const double expected = dst[(y * 8 + x) * 3 + c];
        if (!tv_testing::Close(px[c], expected, 1.5)) {
          std::fprintf(stderr, "resize mismatch at (%d,%d,c=%d): got %d want %.1f\n",
                       y, x, c, px[c], expected);
          std::exit(1);
        }
      }
    }
  }
}

// --- PilBilinear port: bit-exact vs Pillow's actual Image.resize BILINEAR. ----
// This is the DEFAULT runtime kernel (reproduces the Python POC). Pixels must
// match Pillow exactly (tolerance 0), validated at two scale-down ratios.
static void checkPilMatch(const std::vector<uint8_t>& src, int in_h, int in_w,
                          int out_w, int out_h,
                          const std::vector<float>& golden) {
  cv::Mat rgb(in_h, in_w, CV_8UC3);
  for (int y = 0; y < in_h; ++y) {
    for (int x = 0; x < in_w; ++x) {
      cv::Vec3b& px = rgb.at<cv::Vec3b>(y, x);
      px[0] = src[(y * in_w + x) * 3 + 0];
      px[1] = src[(y * in_w + x) * 3 + 1];
      px[2] = src[(y * in_w + x) * 3 + 2];
    }
  }
  cv::Mat out;
  tinyvision::PilBilinearResize(rgb, out_w, out_h, out);
  CHECK(out.rows == out_h && out.cols == out_w && out.type() == CV_8UC3);
  for (int y = 0; y < out_h; ++y) {
    for (int x = 0; x < out_w; ++x) {
      const cv::Vec3b& px = out.at<cv::Vec3b>(y, x);
      for (int c = 0; c < 3; ++c) {
        const double expected = golden[(y * out_w + x) * 3 + c];
        if (px[c] != static_cast<int>(expected)) {
          std::fprintf(stderr,
                       "PilBilinear mismatch at (%d,%d,c=%d): got %d want %.0f\n",
                       y, x, c, px[c], expected);
          std::exit(1);
        }
      }
    }
  }
}

TEST(PilBilinearMatchesPillowSmall) {
  const std::vector<uint8_t> real_src =
      tv_testing::LoadNpyU8("runtime/tests/golden_resize_area_src.npy");  // 16x32
  const std::vector<float> dst =
      tv_testing::LoadNpyF32("runtime/tests/golden_pil_bilinear_16x32_8x8.npy");
  checkPilMatch(real_src, 16, 32, 8, 8, dst);
}

TEST(PilBilinearMatchesPillowLarge) {
  const std::vector<uint8_t> src =
      tv_testing::LoadNpyU8("runtime/tests/golden_pil_bilinear_src_big.npy");  // 180x320
  const std::vector<float> dst =
      tv_testing::LoadNpyF32("runtime/tests/golden_pil_bilinear_320x180_224x224.npy");
  checkPilMatch(src, 180, 320, 224, 224, dst);
}

// --- PreprocessLayoutAndNormalize: hand-computed normalisation/layout. ---
TEST(PreprocessLayoutAndNormalize) {
  const int n = 4;
  cv::Mat bgr(n, n, CV_8UC3, cv::Scalar(64, 128, 192));
  // Colors in RGB order: R=192, G=128, B=64 (after BGR->RGB).
  std::vector<float> out;
  tinyvision::PreprocessFrame(bgr, n, out, tinyvision::ResizeMode::kArea);
  CHECK(out.size() == static_cast<size_t>(3 * n * n));

  const double r = (192 / 255.0 - 0.485) / 0.229;
  const double g = (128 / 255.0 - 0.456) / 0.224;
  const double b = (64 / 255.0 - 0.406) / 0.225;
  auto idx = [n](int c, int y, int x) {
    return static_cast<size_t>(c) * n * n + y * n + x;
  };
  for (int y = 0; y < n; ++y) {
    for (int x = 0; x < n; ++x) {
      CHECK(tv_testing::Close(out[idx(0, y, x)], r, 1e-6));
      CHECK(tv_testing::Close(out[idx(1, y, x)], g, 1e-6));
      CHECK(tv_testing::Close(out[idx(2, y, x)], b, 1e-6));
    }
  }
}

TEST(PreprocessEmptyThrows) {
  cv::Mat empty;
  std::vector<float> out;
  bool threw = false;
  try {
    tinyvision::PreprocessFrame(empty, 224, out, tinyvision::ResizeMode::kArea);
  } catch (const std::runtime_error&) {
    threw = true;
  }
  CHECK(threw);
}